        return None
    if apagar:
        try:
            os.remove(f'{local}\{empresa}_{ano}.db')
        except:
            st.error(f"Sem permissão para deletar o arquivo {local}\{empresa}_{ano}.db.")

    con = sl.connect(f'{local}\{empresa}_{ano}.db')
